//! 🎟️ Original transaction admission conserves exact native allocations and unchanged borrowed inputs.
use super::*;
#[test]
fn original_tool_transaction_admission_preserves_fixed_grants_and_physical_custody(){
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let clock=crate::ids::HybridLogicalTimestamp{actor:law["clock"]["actor"].as_u64().unwrap(),physical_ms:law["clock"]["physicalMs"].as_u64().unwrap(),logical:law["clock"]["logical"].as_u64().unwrap()};
 let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:4096,maximum_release_bytes:262144,maximum_depth:4096};
 for actor in law["actors"].as_array().unwrap(){for app in law["apps"].as_array().unwrap(){for tool in law["tools"].as_array().unwrap(){
  let(actor,app,tool)=(actor.as_str().unwrap(),app.as_str().unwrap(),tool.as_str().unwrap());let pointers=(actor.as_ptr(),app.as_ptr(),tool.as_ptr());
  let(demand,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||tool_transaction_demand(actor,app,tool).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(demand.copy_bytes<=grant.maximum_copy_bytes);assert!(demand.capacity_bytes<=grant.maximum_capacity_bytes);
  for denied in[RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..grant},RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_tool_transaction(actor,&clock,app,tool,denied).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((actor.as_ptr(),app.as_ptr(),tool.as_ptr()),pointers);}
  let((transaction,receipt),birth)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_tool_transaction(actor,&clock,app,tool,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!((birth.requested_bytes,birth.released_bytes),(receipt.retained_capacity_bytes,0));assert_eq!(transaction.tool,format!("{app}#{tool}"));
  let mut material=Vec::new();crate::write_str(&mut material,actor);crate::wire::write_varint_u64(&mut material,clock.actor);crate::wire::write_varint_u64(&mut material,clock.physical_ms);crate::wire::write_varint_u64(&mut material,clock.logical);crate::write_str(&mut material,&transaction.tool);assert_eq!(transaction.id,format!("tx-{}",&blake3::hash(&material).to_hex()[..16]));
  let pointers=(transaction.id.as_ptr(),transaction.tool.as_ptr());let mut owner=ControlledRetirement::new(transaction).unwrap();assert_eq!((owner.original().unwrap().id.as_ptr(),owner.original().unwrap().tool.as_ptr()),pointers);let mut capacity=birth.requested_bytes;let mut release=0;let mut turns=0;
  while !owner.terminal_is_empty(){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));capacity+=heap.requested_bytes;release+=heap.released_bytes;turns+=1;assert!(turns<100000);}
  assert_eq!(capacity,release);let((),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] original tool transaction fixed grant copy4096/cap4096; BLAKE3 oracle, original pointers, turns={turns}, physical={release}, terminalDrop0");
 }}}
 let actor="giant🧩".repeat(8192);let pointer=actor.as_ptr();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_tool_transaction(&actor,&clock,"draw","select",grant).unwrap());assert!(result.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(actor.as_ptr(),pointer);
}
